package com.musicplaylist.controller;
import com.musicplaylist.util.*;import jakarta.servlet.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import java.io.*;import java.sql.*;
@WebServlet("/playlists/add-song") public class AddToPlaylistServlet extends HttpServlet {protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{Integer uid=Auth.userId(q);if(uid==null){p.sendRedirect(q.getContextPath()+"/login");return;}try(Connection c=DBConnection.getConnection()){int pl=Integer.parseInt(q.getParameter("playlistId")),song=Integer.parseInt(q.getParameter("songId"));try(PreparedStatement k=c.prepareStatement("SELECT id FROM playlists WHERE id=? AND user_id=?")){k.setInt(1,pl);k.setInt(2,uid);try(ResultSet r=k.executeQuery()){if(!r.next()){p.sendError(403);return;}}}try(PreparedStatement s=c.prepareStatement("INSERT IGNORE INTO playlist_songs VALUES(?,?)")){s.setInt(1,pl);s.setInt(2,song);s.executeUpdate();}p.sendRedirect(q.getContextPath()+"/dashboard");}catch(SQLException|NumberFormatException x){throw new ServletException(x);}}}